from __future__ import annotations

from aiogram import Router
from aiogram.types import CallbackQuery, Message

from bot_app.config import Settings
from bot_app.keyboards import kb_start


def setup(_settings: Settings) -> Router:
    router = Router(name="fallback")

    @router.callback_query()
    async def stale_callback(callback: CallbackQuery) -> None:
        await callback.answer(
            "Эта кнопка устарела. Откройте меню: /start",
            show_alert=False,
        )
        if callback.message:
            try:
                await callback.message.answer(
                    "Нажмите /start, чтобы заново открыть меню.",
                    reply_markup=kb_start(),
                )
            except Exception:
                pass

    @router.message()
    async def unhandled_message(message: Message) -> None:
        # Только личные чаты, не группы
        if message.chat.type != "private":
            return
        if not message.text:
            return
        if message.text.startswith("/"):
            return
        await message.answer(
            "Не понял запрос. Нажмите /start или /help.",
            reply_markup=kb_start(),
        )

    return router

